  for(const o of affected){const k=o.run.index; if(!byRun.has(k))byRun.set(k,[]); byRun.get(k).push(o.x);}
  let best={run:-1,items:[]}; for(const [run,items] of byRun) if(items.length>best.items.length)best={run,items};
  if(best.run<0)return null;
  const groups=[...new Set(best.items.map(x=>x.imageGroup).filter(Boolean))];
  const sameGroupPeers=peers.filter(x=>x.imageGroup===target.imageGroup);
