(function(AOI){
const { buildItemKey } = AOI;

const rank={accepted:0,conditional:1,rejected:2,pending:3};
function compareRecords(beforeItems, afterItems, options={}){
  const epsilon=Number.isFinite(options.unchangedEpsilon)?options.unchangedEpsilon:0.01;
  const bmap=new Map(beforeItems.map(x=>[buildItemKey(x),x]));
  const amap=new Map(afterItems.map(x=>[buildItemKey(x),x]));
  const matched=[], beforeOnly=[], afterOnly=[];
  for(const [key,b] of bmap){
    const a=amap.get(key);
    if(!a){beforeOnly.push(b);continue;}
    const before=Number(b.metrics?.sixSigmaPercent), after=Number(a.metrics?.sixSigmaPercent), delta=after-before;
    let change;
    if(rank[a.status] < rank[b.status]) change='cross_grade_improvement';
    else if(rank[a.status] > rank[b.status]) change='cross_grade_worsening';
    else if(Math.abs(delta)<=epsilon) change='unchanged';
    else if(delta<0) change='improved';
    else change='worsened';
    matched.push({key,item:b.item,product:b.product,before,after,delta,beforeStatus:b.status,afterStatus:a.status,change,beforeItem:b,afterItem:a});
  }
  for(const [key,a] of amap) if(!bmap.has(key)) afterOnly.push(a);
  const summary={improved:0,worsened:0,unchanged:0,crossGradeImprovement:0,crossGradeWorsening:0};
  for(const m of matched){
    if(m.change==='improved')summary.improved++;
    else if(m.change==='worsened')summary.worsened++;
    else if(m.change==='unchanged')summary.unchanged++;
    else if(m.change==='cross_grade_improvement'){summary.improved++;summary.crossGradeImprovement++;}
    else if(m.change==='cross_grade_worsening'){summary.worsened++;summary.crossGradeWorsening++;}
  }
  return {matched,beforeOnly,afterOnly,summary};
}

Object.assign(AOI,{compareRecords});
})(window.AOI);

(function(AOI){

const DB_VERSION = 1;
const DB_NAME = 'aoi-lab-repeatability';
const STORES=['projects','records','experience','settings'];

function makeBackupPayload(data={}){
  return {
    schemaVersion: DB_VERSION,
    exportedAt: new Date().toISOString(),
    projects: Array.isArray(data.projects)?data.projects:[],
    records: Array.isArray(data.records)?data.records:[],
    experience: Array.isArray(data.experience)?data.experience:[],
    settings: Array.isArray(data.settings)?data.settings:[]
  };
}
function validateBackupPayload(p){
  return !!p && Number.isInteger(p.schemaVersion) && p.schemaVersion>0 && p.schemaVersion<=DB_VERSION && STORES.every(k=>Array.isArray(p[k]));
}

function openAoiDb(){
  if(typeof indexedDB==='undefined') return Promise.reject(new Error('IndexedDB unavailable'));
  return new Promise((resolve,reject)=>{
    const req=indexedDB.open(DB_NAME,DB_VERSION);
    req.onupgradeneeded=()=>{
      const db=req.result;
      if(!db.objectStoreNames.contains('projects')) db.createObjectStore('projects',{keyPath:'id'});
      if(!db.objectStoreNames.contains('records')) db.createObjectStore('records',{keyPath:'id'});
      if(!db.objectStoreNames.contains('experience')) db.createObjectStore('experience',{keyPath:'id'});
      if(!db.objectStoreNames.contains('settings')) db.createObjectStore('settings',{keyPath:'key'});
    };
    req.onsuccess=()=>resolve(req.result); req.onerror=()=>reject(req.error);
  });
}
function request(req){return new Promise((res,rej)=>{req.onsuccess=()=>res(req.result);req.onerror=()=>rej(req.error);});}
async function tx(store,mode,fn){const db=await openAoiDb();try{const t=db.transaction(store,mode);const out=await fn(t.objectStore(store));await new Promise((res,rej)=>{t.oncomplete=res;t.onerror=()=>rej(t.error);t.onabort=()=>rej(t.error||new Error('transaction aborted'));});return out;}finally{db.close();}}
async function listStore(store){return tx(store,'readonly',s=>request(s.getAll()));}
async function putStore(store,value){return tx(store,'readwrite',s=>request(s.put(value)));}
async function deleteStore(store,key){return tx(store,'readwrite',s=>request(s.delete(key)));}
async function saveProject(project){return putStore('projects',project);}
async function saveRecord(record){return putStore('records',record);}
async function saveExperience(entry){return putStore('experience',entry);}
async function getAllLocalData(){const [projects,records,experience,settings]=await Promise.all(STORES.map(listStore));return {projects,records,experience,settings};}
async function importBackupPayload(payload){
  if(!validateBackupPayload(payload)) throw new Error('无效或不兼容的 AOI LAB 备份');
  const db=await openAoiDb();
  try{
    for(const store of STORES){
      await new Promise((resolve,reject)=>{
        const t=db.transaction(store,'readwrite'); const s=t.objectStore(store); s.clear(); for(const row of payload[store]) s.put(row);
        t.oncomplete=resolve;t.onerror=()=>reject(t.error);t.onabort=()=>reject(t.error||new Error('transaction aborted'));
      });
    }
  } finally {db.close();}
}
async function experienceCounts(analysisId){
  const rows=await listStore('experience'); const globalCounts={},projectCounts={};
  for(const r of rows){const code=r.actualCauseCode||r.systemCauseCode;if(!code)continue;globalCounts[code]=(globalCounts[code]||0)+1;const scope=String(r.analysisId||r.projectId||'');if(analysisId&&scope===String(analysisId))projectCounts[code]=(projectCounts[code]||0)+1;}
  return {globalCounts,projectCounts};
}

Object.assign(AOI,{DB_VERSION,DB_NAME,makeBackupPayload,validateBackupPayload,openAoiDb,listStore,putStore,deleteStore,saveProject,saveRecord,saveExperience,getAllLocalData,importBackupPayload,experienceCounts});
})(window.AOI);

